            text: "The designers of a cache system need to reduce the number of cache misses that occur in a certain group of programs. Which of the following statements is/are true?<br><br><b> \\( S_1 \\) : </b> If compulsory misses are most common, then the designers should consider increasing the cache line size to take better advantage of locality.<br><br><b> \\( S_2 \\) : </b> If capacity misses are most common, then the designers should consider increasing the total cache size so it can contain more lines.<br><br><b> \\( S_3 \\) : </b> If conflict misses are most common, then the designers should consider increasing the cache’s associativity, in order to provide more flexibility when a collision occurs.",
            image: "",
