            answer: "B",
            solution: "Counting sort is stable. It is not in-place, however, since we must make additional space  to store the counts of the various elements. This space requirement grows as the size of  the input increases. Additionally, we have to make a separate output array to produce the  answer using counting sort. So, S <sub>1</sub> is incorrect.<br>At the top level, roughly n work is done to merge all n elements. At the next level,  there are two branches, each doing roughly n /2 work to merge n /2 elements.  In total, roughly n work is done on that level. This pattern continues on through to the  leaves, where a constant amount of work is done on n leaves, resulting in roughly n  work being done on the leaf level, as well. So, S <sub>2</sub> is correct."
