            text: "A demand-paged memory system has R page frames. A process repeatedly accesses a fixed  ordered list of S different pages, one after another, and once the last page is  accessed, the same order starts again. Assume: • All S pages are distinct. •  Initially, memory contains no pages. • S > R Which of the following  statements is/are correct?",
            image: "",
            options: [
                'If the number of frames is at least equal to the number of distinct pages, then after  one complete pass through the list, no further page faults will occur.',
                'For this cyclic reference string of S distinct pages, FIFO and LRU will generate  identical pagefault counts for any number of frames less than S.',
                'The most-recently-loaded replacement policy always performs as well as the  optimal replacement policy for this reference pattern.',
                'Suppose S = 2 R . If FIFO is used and the ordered list is executed four  consecutive times, then every page reference results in a page fault.'
            ],
            answer: ["A", "D", "B"],
            solution: "If R ≥ S , then after one full pass, no further page faults occur. During  the first pass, each of the S distinct pages is loaded once. Since frames can hold  all S pages, none will be evicted. In subsequent repetitions, all references are  hits. So, option (a) is correct.<br>FIFO and LRU generate identical page-fault counts when R < S . The access  pattern is strictly cyclic. When we return to the first page in the sequence, at least S – 1 other distinct pages have been accessed. Since S > R , the required  page cannot be in memory. Therefore, every reference causes a fault. This happens for both  FIFO and LRU. So, option (b) is correct.<br>Most-recently-loaded policy (LIFO) performs as well as OPT. LIFO replaces the most recently  loaded page. This policy is not stack-based and can evict pages that will be used very soon.  Optimal replacement looks into the future and is strictly better or equal to any other  policy. So, option (c) is incorrect.<br>Given S = 2 R , FIFO used, list repeated four times. First pass: S faults (memory fills and replaces). At end of pass, memory contains last R  pages. When next pass starts, first R pages are not in memory. Every reference causes a  fault. This continues for all four repetitions. Total references = 4 S Total  faults = 4 S So, option (d) is correct."
