            answer: "B",
            solution: "Linked allocation stores file blocks anywhere on the disk and connects them using  pointers. There is no requirement for contiguous allocation, so external fragmentation does  not occur. So, S <sub>1</sub> is incorrect.<br>Index allocation uses a fixed-size index block pointing to data blocks. The last data block  may not be fully used → internal fragmentation occurs. So, S <sub>2 </sub> is  correct.<br>In linked allocation, each block stores a pointer to the next block. This consumes extra  space per block → pointer overhead. So, S <sub>3</sub> is correct."
