            answer: ["A", "D"],
            solution: '<ul><li>Best fit selects the smallest available hole that satisfies the request. This helps in minimizing&nbsp;wasted space inside memory blocks. However, over time, allocation and deallocation still&nbsp;create scattered holes. Hence, external fragmentation is reduced but not eliminated.<br>So, option (a) is correct.</li><li>Compaction shifts all allocated processes together. It creates one large contiguous free block.&nbsp;However, compaction is not always possible due to relocation cost and overhead. Also,&nbsp;fragmentation can reappear after further allocations. So it does not permanently eliminate&nbsp;external fragmentation.<br>So, option (b) is incorrect.</li><li>Segmentation divides memory into variable-sized logical segments. Allocation is based on&nbsp;exact segment size requirements. So internal fragmentation is minimal or absent. However,&nbsp;external fragmentation can occur between segments.<br>So, option (c) is incorrect.</li><li>First fit searches from the beginning and allocates the first suitable hole. It is fast in allocation&nbsp;compared to other strategies. But repeated allocations leave small unusable gaps. These gaps&nbsp;accumulate and increase external fragmentation.<br>So, option (d) is correct.</li></ul>'
