            solution: '<p>Deadlock can occur only if all four necessary conditions hold simultaneously:<br>1. Mutual exclusion<br>2. Hold and wait<br>3. No preemption<br>4. Circular wait<br>A policy prevents deadlock if it eliminates at least one of these conditions.</p><ul><li>A process either acquires all required resources together or acquires none.<br>Thus, a process never holds some resources while waiting for additional resources.<br>Hence, the hold and wait condition is eliminated.<br>So, option (a) is correct.</li><li>Resources are requested only in increasing order of resource numbers.<br>Therefore, cyclic dependency among processes cannot occur.<br>Hence, the circular wait condition is eliminated.<br>So, option (b) is correct.</li><li>This policy allows a process to continue holding resources while requesting additional resources.<br>Thus, the hold and wait condition still exists.<br>So, option (c) is incorrect.</li><li>If a requested resource is unavailable, the process releases all currently held resources.<br>Thus, resources can effectively be preempted.<br>Hence, the no preemption condition is eliminated.<br>So, option (d) is correct.</li></ul>'
