            answer: ["B", "C", "A"],
            solution: "• An SDD is S-attributed if all attributes are synthesized. Here, every \\(val\\) attribute is computed from attributes of child nodes:<br>\\(E.val = E_1.val + T.val\\)<br>\\(T.val = T_1.val \\times F.val\\)<br>\\(F.val = \\text{num.lexval}\\)<br>No inherited attributes are used, so statement (A) is correct.<br>• Every S-attributed SDD is automatically L-attributed because synthesized attributes satisfy the L-attributed restrictions. So statement (B) is correct.<br>• The attribute \\(val\\) is always computed from child attributes and passed upward (\\(F.val \\to T.val \\to E.val\\)), so \\(val\\) is a synthesized attribute. Statement (C) is correct.<br>• The grammar separates expressions into levels \\(E, T, F\\), '*' has higher precedence than '+', and both are left-associative. Therefore, the grammar is unambiguous. Statement (D) is incorrect."
